#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class PadV3GradReplicationKernel {
public:
    __aicore__ inline PadV3GradReplicationKernel() {}

    __aicore__ inline void Init(
        GM_ADDR gradOutput,
        GM_ADDR gradInput,
        uint32_t n,
        uint32_t c,
        uint32_t h,
        uint32_t w,
        uint32_t outH,
        uint32_t outW,
        uint32_t padTop,
        uint32_t padBottom,
        uint32_t padLeft,
        uint32_t padRight,
        uint32_t ndim,
        uint32_t d,
        uint32_t outD,
        uint32_t padDStart,
        uint32_t padDEnd,
        uint32_t totalLength,
        uint32_t tileLength,
        uint32_t formerNum,
        uint32_t formerLength,
        uint32_t tailNum,
        uint32_t tailLength
    ) {
        // Save tiling params
        this->n = n;
        this->c = c;
        this->h = h;
        this->w = w;
        this->outH = outH;
        this->outW = outW;
        this->padTop = padTop;
        this->padBottom = padBottom;
        this->padLeft = padLeft;
        this->padRight = padRight;
        this->ndim = ndim;
        this->d = d;
        this->outD = outD;
        this->padDStart = padDStart;
        this->padDEnd = padDEnd;
        this->totalLength = totalLength;
        this->tileLength = tileLength;
        this->formerNum = formerNum;
        this->formerLength = formerLength;
        this->tailNum = tailNum;
        this->tailLength = tailLength;

        // Set up GlobalTensor
        gradOutputGm.SetGlobalBuffer((__gm__ T*)gradOutput);
        gradInputGm.SetGlobalBuffer((__gm__ T*)gradInput);

        // Calculate spatial strides for grad_output
        if (ndim == 4) {
            outStrideW = 1;
            outStrideH = outW;
            outStrideC = outH * outW;
            outStrideN = c * outH * outW;

            inStrideW = 1;
            inStrideH = w;
            inStrideC = h * w;
            inStrideN = c * h * w;
        } else {
            outStrideW = 1;
            outStrideH = outW;
            outStrideD = outH * outW;
            outStrideC = outD * outH * outW;
            outStrideN = c * outD * outH * outW;

            inStrideW = 1;
            inStrideH = w;
            inStrideD = h * w;
            inStrideC = d * h * w;
            inStrideN = c * d * h * w;
        }

        // Allocate pipe buffers
        pipe.InitBuffer(inQueue, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueue, BUFFER_NUM, tileLength * sizeof(T));

        if constexpr (sizeof(T) == sizeof(half)) {
            pipe.InitBuffer(castBuf, BUFFER_NUM, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process() {
        uint32_t loopCount = formerNum + tailNum;
        for (uint32_t i = 0; i < loopCount; ++i) {
            uint32_t curTileLength = (i < formerNum) ? formerLength : tailLength;
            CopyIn(i, curTileLength);
            Compute(i, curTileLength);
            CopyOut(i, curTileLength);
        }
    }

private:
    __aicore__ inline void CopyIn(uint32_t progress, uint32_t curTileLength) {
        // For this kernel, we compute directly from grad_output GM
        // No need to copy in a tile since we access scattered positions
        // But we need to initialize output buffer
        LocalTensor<T> outLocal = outQueue.AllocTensor<T>();
        AscendC::Duplicate(outLocal, T(0), curTileLength);
        outQueue.EnQue(outLocal);
    }

    __aicore__ inline void Compute(uint32_t progress, uint32_t curTileLength) {
        LocalTensor<T> outLocal = outQueue.DeQue<T>();

        uint32_t elemStart = progress * tileLength;

        if (ndim == 4) {
            Compute4D(outLocal, elemStart, curTileLength);
        } else {
            Compute5D(outLocal, elemStart, curTileLength);
        }

        outQueue.EnQue(outLocal);
    }

    __aicore__ inline void Compute4D(LocalTensor<T>& outLocal, uint32_t elemStart, uint32_t count) {
        for (uint32_t idx = 0; idx < count; ++idx) {
            uint32_t globalIdx = elemStart + idx;
            if (globalIdx >= totalLength) break;

            // Decompose globalIdx into (ni, ci, hi, wi)
            uint32_t ni = globalIdx / inStrideN;
            uint32_t rem = globalIdx % inStrideN;
            uint32_t ci = rem / inStrideC;
            rem = rem % inStrideC;
            uint32_t hi = rem / inStrideH;
            uint32_t wi = rem % inStrideH;

            // Compute corresponding position in grad_output
            uint32_t goH = hi + padTop;
            uint32_t goW = wi + padLeft;

            // Determine contributing grad_output rows
            uint32_t hStart, hEnd;
            if (hi == 0) {
                hStart = 0;
                hEnd = padTop + 1;
            } else if (hi == h - 1) {
                hStart = goH;
                hEnd = outH;
            } else {
                hStart = goH;
                hEnd = goH + 1;
            }

            float sum = 0.0f;

            for (uint32_t gh = hStart; gh < hEnd; ++gh) {
                // Determine contributing columns
                uint32_t wStart, wEnd;
                if (wi == 0) {
                    wStart = 0;
                    wEnd = padLeft + 1;
                } else if (wi == w - 1) {
                    wStart = goW;
                    wEnd = outW;
                } else {
                    wStart = goW;
                    wEnd = goW + 1;
                }

                for (uint32_t gw = wStart; gw < wEnd; ++gw) {
                    uint32_t goIdx = ni * outStrideN + ci * outStrideC + gh * outStrideH + gw * outStrideW;
                    float val = CastToFloat(gradOutputGm.GetValue(goIdx));
                    sum += val;
                }
            }

            outLocal.SetValue(idx, CastFromFloat(sum));
        }
    }

    __aicore__ inline void Compute5D(LocalTensor<T>& outLocal, uint32_t elemStart, uint32_t count) {
        for (uint32_t idx = 0; idx < count; ++idx) {
            uint32_t globalIdx = elemStart + idx;
            if (globalIdx >= totalLength) break;

            // Decompose globalIdx into (ni, ci, di, hi, wi)
            uint32_t ni = globalIdx / inStrideN;
            uint32_t rem = globalIdx % inStrideN;
            uint32_t ci = rem / inStrideC;
            rem = rem % inStrideC;
            uint32_t di = rem / inStrideD;
            rem = rem % inStrideD;
            uint32_t hi = rem / inStrideH;
            uint32_t wi = rem % inStrideH;

            // Compute corresponding position in grad_output
            uint32_t goD = di + padDStart;
            uint32_t goH = hi + padTop;
            uint32_t goW = wi + padLeft;

            // Determine contributing depth slices
            uint32_t dStart, dEnd;
            if (di == 0) {
                dStart = 0;
                dEnd = padDStart + 1;
            } else if (di == d - 1) {
                dStart = goD;
                dEnd = outD;
            } else {
                dStart = goD;
                dEnd = goD + 1;
            }

            // Determine contributing height rows
            uint32_t hStart, hEnd;
            if (hi == 0) {
                hStart = 0;
                hEnd = padTop + 1;
            } else if (hi == h - 1) {
                hStart = goH;
                hEnd = outH;
            } else {
                hStart = goH;
                hEnd = goH + 1;
            }

            // Determine contributing width columns
            uint32_t wStart, wEnd;
            if (wi == 0) {
                wStart = 0;
                wEnd = padLeft + 1;
            } else if (wi == w - 1) {
                wStart = goW;
                wEnd = outW;
            } else {
                wStart = goW;
                wEnd = goW + 1;
            }

            float sum = 0.0f;

            for (uint32_t gd = dStart; gd < dEnd; ++gd) {
                for (uint32_t gh = hStart; gh < hEnd; ++gh) {
                    for (uint32_t gw = wStart; gw < wEnd; ++gw) {
                        uint32_t goIdx = ni * outStrideN + ci * outStrideC + gd * outStrideD
                                       + gh * outStrideH + gw * outStrideW;
                        float val = CastToFloat(gradOutputGm.GetValue(goIdx));
                        sum += val;
                    }
                }
            }

            outLocal.SetValue(idx, CastFromFloat(sum));
        }
    }

    __aicore__ inline float CastToFloat(T val) {
        if constexpr (std::is_same_v<T, float>) {
            return val;
        } else {
            return static_cast<float>(val);
        }
    }

    __aicore__ inline T CastFromFloat(float val) {
        if constexpr (std::is_same_v<T, float>) {
            return val;
        } else {
            return static_cast<T>(val);
        }
    }

    __aicore__ inline void CopyOut(uint32_t progress, uint32_t curTileLength) {
        LocalTensor<T> outLocal = outQueue.DeQue<T>();
        uint32_t offset = progress * tileLength;
        AscendC::DataCopyPad(gradInputGm[offset], outLocal, curTileLength);
        outQueue.FreeTensor(outLocal);
    }

private:
    // TPipe and TQue
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::QuePosition::VECIN, BUFFER_NUM> inQueue;
    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> outQueue;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> castBuf;

    // Global tensors
    AscendC::GlobalTensor<T> gradOutputGm;
    AscendC::GlobalTensor<T> gradInputGm;

    // Shape params
    uint32_t n, c, h, w, outH, outW;
    uint32_t padTop, padBottom, padLeft, padRight;
    uint32_t ndim, d, outD, padDStart, padDEnd;

    // Tiling params
    uint32_t totalLength, tileLength;
    uint32_t formerNum, formerLength, tailNum, tailLength;

    // Strides for 4D
    uint32_t outStrideW, outStrideH, outStrideC, outStrideN;
    uint32_t inStrideW, inStrideH, inStrideC, inStrideN;
    // Strides for 5D
    uint32_t outStrideD, inStrideD;
};

extern "C" __global__ __aicore__ void padv3gradreplication(
    GM_ADDR gradOutput,
    GM_ADDR gradInput,
    GM_ADDR tiling
) {
    // Read tiling data from GM
    __gm__ uint32_t* tilingPtr = (__gm__ uint32_t*)tiling;
    uint32_t n = tilingPtr[0];
    uint32_t c = tilingPtr[1];
    uint32_t h = tilingPtr[2];
    uint32_t w = tilingPtr[3];
    uint32_t outH = tilingPtr[4];
    uint32_t outW = tilingPtr[5];
    uint32_t padTop = tilingPtr[6];
    uint32_t padBottom = tilingPtr[7];
    uint32_t padLeft = tilingPtr[8];
    uint32_t padRight = tilingPtr[9];
    uint32_t ndim = tilingPtr[10];
    uint32_t d = tilingPtr[11];
    uint32_t outD = tilingPtr[12];
    uint32_t padDStart = tilingPtr[13];
    uint32_t padDEnd = tilingPtr[14];
    uint32_t totalLength = tilingPtr[15];
    uint32_t tileLength = tilingPtr[16];
    uint32_t formerNum = tilingPtr[17];
    uint32_t formerLength = tilingPtr[18];
    uint32_t tailNum = tilingPtr[19];
    uint32_t tailLength = tilingPtr[20];
    uint32_t dtypeSize = tilingPtr[21];

    if (dtypeSize == sizeof(float)) {
        PadV3GradReplicationKernel<float> op;
        op.Init(gradOutput, gradInput, n, c, h, w, outH, outW,
                padTop, padBottom, padLeft, padRight, ndim, d, outD,
                padDStart, padDEnd, totalLength, tileLength,
                formerNum, formerLength, tailNum, tailLength);
        op.Process();
    } else {
        PadV3GradReplicationKernel<half> op;
        op.Init(gradOutput, gradInput, n, c, h, w, outH, outW,
                padTop, padBottom, padLeft, padRight, ndim, d, outD,
                padDStart, padDEnd, totalLength, tileLength,
                formerNum, formerLength, tailNum, tailLength);
        op.Process();
    }
}
