#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_padv3gradreplication.h"

namespace ascend_kernel {

at::Tensor padv3gradreplication(
    const at::Tensor& grad_output,
    at::IntArrayRef padding
) {
    // Validate input
    TORCH_CHECK(grad_output.dim() == 4 || grad_output.dim() == 5,
                "PadV3GradReplication only supports 4D and 5D tensors");
    TORCH_CHECK(grad_output.is_contiguous(), "Input tensor must be contiguous");

    auto dtype = grad_output.scalar_type();
    TORCH_CHECK(dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16,
                "PadV3GradReplication only supports float32, float16, bfloat16");

    int64_t ndim = grad_output.dim();
    auto shape = grad_output.sizes();

    // Parse padding (GE format: 10 elements)
    auto pad_vec = padding.vec();
    TORCH_CHECK(pad_vec.size() == 10,
                "Padding must be 10-element GE format");

    int64_t pad_top = pad_vec[4];
    int64_t pad_bottom = pad_vec[5];
    int64_t pad_left = pad_vec[8];
    int64_t pad_right = pad_vec[9];

    int64_t n = shape[0];
    int64_t c = shape[1];
    int64_t out_h = shape[2];
    int64_t out_w = shape[3];
    int64_t h = out_h - pad_top - pad_bottom;
    int64_t w = out_w - pad_left - pad_right;

    int64_t d = 1, out_d = 1, pad_d_start = 0, pad_d_end = 0;
    if (ndim == 5) {
        out_h = shape[3];
        out_w = shape[4];
        h = out_h - pad_top - pad_bottom;
        w = out_w - pad_left - pad_right;
        d = shape[2] - pad_vec[4] - pad_vec[5];
        out_d = shape[2];
        pad_d_start = pad_vec[4];
        pad_d_end = pad_vec[5];
        // Re-read padding for 5D
        pad_top = pad_vec[6];
        pad_bottom = pad_vec[7];
        pad_left = pad_vec[8];
        pad_right = pad_vec[9];
        h = out_h - pad_top - pad_bottom;
        w = out_w - pad_left - pad_right;
        d = shape[2] - pad_d_start - pad_d_end;
    }

    TORCH_CHECK(h > 0 && w > 0, "Invalid padding: output spatial dims must be positive");
    if (ndim == 5) {
        TORCH_CHECK(d > 0, "Invalid padding: output depth must be positive");
    }

    // Create output tensor
    std::vector<int64_t> out_shape;
    if (ndim == 4) {
        out_shape = {n, c, h, w};
    } else {
        out_shape = {n, c, d, h, w};
    }
    auto grad_input = at::empty(out_shape, grad_output.options());

    // Get platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Calculate total output elements
    int64_t totalLength = grad_input.numel();

    // Block-level tiling
    int64_t totalLengthCoreAlign = (totalLength + coreNum - 1) / coreNum;
    totalLengthCoreAlign = (totalLengthCoreAlign + 127) / 128 * 128; // 128B align

    int64_t formerNum = totalLength / totalLengthCoreAlign;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailNum = (totalLength % totalLengthCoreAlign != 0) ? 1 : 0;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // UB-level tiling
    int64_t bufferCoefficient = (dtype == at::kFloat) ? 20 : 16;
    int64_t tileLength = (ubSize / bufferCoefficient) / sizeof(float);
    tileLength = (tileLength + 7) / 8 * 8; // 8-element align
    if (tileLength > totalLengthCoreAlign) {
        tileLength = totalLengthCoreAlign;
    }
    if (tileLength < 8) {
        tileLength = 8;
    }

    // Tiling data (22 uint32_t values)
    uint32_t tilingData[22];
    tilingData[0] = static_cast<uint32_t>(n);
    tilingData[1] = static_cast<uint32_t>(c);
    tilingData[2] = static_cast<uint32_t>(h);
    tilingData[3] = static_cast<uint32_t>(w);
    tilingData[4] = static_cast<uint32_t>(out_h);
    tilingData[5] = static_cast<uint32_t>(out_w);
    tilingData[6] = static_cast<uint32_t>(pad_top);
    tilingData[7] = static_cast<uint32_t>(pad_bottom);
    tilingData[8] = static_cast<uint32_t>(pad_left);
    tilingData[9] = static_cast<uint32_t>(pad_right);
    tilingData[10] = static_cast<uint32_t>(ndim);
    tilingData[11] = static_cast<uint32_t>(d);
    tilingData[12] = static_cast<uint32_t>(out_d);
    tilingData[13] = static_cast<uint32_t>(pad_d_start);
    tilingData[14] = static_cast<uint32_t>(pad_d_end);
    tilingData[15] = static_cast<uint32_t>(totalLength);
    tilingData[16] = static_cast<uint32_t>(tileLength);
    tilingData[17] = static_cast<uint32_t>(formerNum);
    tilingData[18] = static_cast<uint32_t>(formerLength);
    tilingData[19] = static_cast<uint32_t>(tailNum);
    tilingData[20] = static_cast<uint32_t>(tailLength);
    tilingData[21] = (dtype == at::kFloat) ? sizeof(float) : sizeof(half);

    // Allocate workspace for tiling data
    auto tiling_tensor = at::empty({22}, at::tensor_options().dtype(at::kInt));
    memcpy(tiling_tensor.data_ptr(), tilingData, sizeof(tilingData));

    int64_t blockDim = coreNum;
    int64_t dtypeSize = tilingData[21];

    // Launch kernel
    EXEC_KERNEL_CMD(padv3gradreplication, blockDim,
                    grad_output, grad_input, tiling_tensor,
                    totalLength, tileLength, formerNum, formerLength,
                    tailNum, tailLength, dtypeSize);

    return grad_input;
}

} // namespace ascend_kernel
