84	            outStrideC = outD * outH * outW;
85	            outStrideN = c * outD * outH * outW;
86	
87	            inStrideW = 1;
88	            inStrideH = w;
89	            inStrideD = h * w;
90	            inStrideC = d * h * w;
91	            inStrideN = c * d * h * w;
92	        }
93	
94	        pipe.InitBuffer(inQueue, BUFFER_NUM, tileLength * sizeof(T));
95	        pipe.InitBuffer(outQueue, BUFFER_NUM, tileLength * sizeof(T));
96	    }
