98	    __aicore__ inline void Process() {
99	        uint32_t loopCount = formerNum + tailNum;
100	        for (uint32_t i = 0; i < loopCount; ++i) {
101	            uint32_t curTileLength = (i < formerNum) ? formerLength : tailLength;
102	            CopyIn(i, curTileLength);
103	            Compute(i, curTileLength);
104	            CopyOut(i, curTileLength);
105	        }
106	    }
