115	    __aicore__ inline void Compute(uint32_t progress, uint32_t curTileLength) {
116	        LocalTensor<T> outLocal = outQueue.DeQue<T>();
117	        uint32_t elemStart = progress * tileLength;
118	
119	        if (ndim == 4) {
120	            Compute4D(outLocal, elemStart, curTileLength);
121	        } else {
122	            Compute5D(outLocal, elemStart, curTileLength);
123	        }
124	
