128	    __aicore__ inline void Compute4D(LocalTensor<T>& outLocal, uint32_t elemStart, uint32_t count) {
129	        for (uint32_t idx = 0; idx < count; ++idx) {
130	            uint32_t globalIdx = elemStart + idx;
131	            if (globalIdx >= totalLength) break;
132	
133	            uint32_t ni = globalIdx / inStrideN;
134	            uint32_t rem = globalIdx % inStrideN;
135	            uint32_t ci = rem / inStrideC;
136	            rem = rem % inStrideC;
137	            uint32_t hi = rem / inStrideH;
138	            uint32_t wi = rem % inStrideH;
139	
140	            uint32_t goH = hi + padTop;
141	            uint32_t goW = wi + padLeft;
142	
143	            uint32_t hStart, hEnd;
144	            if (hi == 0) {
145	                hStart = 0;
146	                hEnd = padTop + 1;
147	            } else if (hi == h - 1) {
148	                hStart = goH;
149	                hEnd = outH;
150	            } else {
151	                hStart = goH;
152	                hEnd = goH + 1;
153	            }
154	
155	            float sum = 0.0f;
156	
157	            for (uint32_t gh = hStart; gh < hEnd; ++gh) {
158	                uint32_t wStart, wEnd;
159	                if (wi == 0) {
160	                    wStart = 0;
161	                    wEnd = padLeft + 1;
162	                } else if (wi == w - 1) {
163	                    wStart = goW;
164	                    wEnd = outW;
165	                } else {
166	                    wStart = goW;
167	                    wEnd = goW + 1;
168	                }
169	
170	                for (uint32_t gw = wStart; gw < wEnd; ++gw) {
171	                    uint32_t goIdx = ni * outStrideN + ci * outStrideC + gh * outStrideH + gw * outStrideW;
172	                    float val = CastToFloat(gradOutputGm.GetValue(goIdx));
173	                    sum += val;
174	                }
175	            }
176	
177	            outLocal.SetValue(idx, CastFromFloat(sum));
178	        }
179	    }
