181	    __aicore__ inline void Compute5D(LocalTensor<T>& outLocal, uint32_t elemStart, uint32_t count) {
182	        for (uint32_t idx = 0; idx < count; ++idx) {
183	            uint32_t globalIdx = elemStart + idx;
184	            if (globalIdx >= totalLength) break;
185	
186	            uint32_t ni = globalIdx / inStrideN;
187	            uint32_t rem = globalIdx % inStrideN;
188	            uint32_t ci = rem / inStrideC;
189	            rem = rem % inStrideC;
190	            uint32_t di = rem / inStrideD;
191	            rem = rem % inStrideD;
192	            uint32_t hi = rem / inStrideH;
193	            uint32_t wi = rem % inStrideH;
194	
195	            uint32_t goD = di + padDStart;
196	            uint32_t goH = hi + padTop;
197	            uint32_t goW = wi + padLeft;
198	
199	            uint32_t dStart, dEnd;
200	            if (di == 0) {
201	                dStart = 0;
202	                dEnd = padDStart + 1;
203	            } else if (di == d - 1) {
204	                dStart = goD;
205	                dEnd = outD;
206	            } else {
207	                dStart = goD;
208	                dEnd = goD + 1;
209	            }
210	
211	            uint32_t hStart, hEnd;
212	            if (hi == 0) {
213	                hStart = 0;
214	                hEnd = padTop + 1;
215	            } else if (hi == h - 1) {
216	                hStart = goH;
217	                hEnd = outH;
218	            } else {
219	                hStart = goH;
220	                hEnd = goH + 1;
221	            }
222	
223	            uint32_t wStart, wEnd;
224	            if (wi == 0) {
225	                wStart = 0;
226	                wEnd = padLeft + 1;
227	            } else if (wi == w - 1) {
228	                wStart = goW;
229	                wEnd = outW;
230	            } else {
231	                wStart = goW;
232	                wEnd = goW + 1;
233	            }
234	
235	            float sum = 0.0f;
236	
237	            for (uint32_t gd = dStart; gd < dEnd; ++gd) {
238	                for (uint32_t gh = hStart; gh < hEnd; ++gh) {
239	                    for (uint32_t gw = wStart; gw < wEnd; ++gw) {
240	                        uint32_t goIdx = ni * outStrideN + ci * outStrideC + gd * outStrideD
241	                                       + gh * outStrideH + gw * outStrideW;
242	                        float val = CastToFloat(gradOutputGm.GetValue(goIdx));
243	                        sum += val;
244	                    }
245	                }
246	            }
247	
248	            outLocal.SetValue(idx, CastFromFloat(sum));
249	        }
