22	namespace ascend_kernel {
23	
24	at::Tensor padv3gradreplication(
25	    const at::Tensor& grad_output,
26	    at::IntArrayRef padding
27	) {
28	    // Validate input
29	    TORCH_CHECK(grad_output.dim() == 4 || grad_output.dim() == 5,
30	                "PadV3GradReplication only supports 4D and 5D tensors");
31	    TORCH_CHECK(grad_output.is_contiguous(), "Input tensor must be contiguous");
32	
33	    auto dtype = grad_output.scalar_type();
34	    TORCH_CHECK(dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16,
35	                "PadV3GradReplication only supports float32, float16, bfloat16");
36	
37	    int64_t ndim = grad_output.dim();
38	    auto shape = grad_output.sizes();
39	
40	    // Parse padding (GE format: 10 elements)
41	    auto pad_vec = padding.vec();
42	    TORCH_CHECK(pad_vec.size() == 10,
43	                "Padding must be 10-element GE format");
44	
45	    // GE format: [0,0,0,0, dl,dr, hl,hr, wl,wr] for 5D
46	    // GE format: [0,0,0,0, 0,0, pt,pb, pl,pr] for 4D
47	    int64_t pad_top, pad_bottom, pad_left, pad_right;
48	    int64_t d = 1, out_d = 1, pad_d_start = 0, pad_d_end = 0;
49	
50	    int64_t n = shape[0];
51	    int64_t c = shape[1];
52	    int64_t out_h, out_w, h, w;
53	
54	    if (ndim == 4) {
55	        // 4D: [0,0,0,0, 0,0, pt,pb, pl,pr]
56	        pad_top = pad_vec[6];
57	        pad_bottom = pad_vec[7];
58	        pad_left = pad_vec[8];
59	        pad_right = pad_vec[9];
60	        out_h = shape[2];
61	        out_w = shape[3];
62	        h = out_h - pad_top - pad_bottom;
63	        w = out_w - pad_left - pad_right;
64	    } else {
65	        // 5D: [0,0,0,0, dl,dr, hl,hr, wl,wr]
66	        pad_d_start = pad_vec[4];
67	        pad_d_end = pad_vec[5];
68	        pad_top = pad_vec[6];
69	        pad_bottom = pad_vec[7];
70	        pad_left = pad_vec[8];
71	        pad_right = pad_vec[9];
72	        out_d = shape[2];
73	        out_h = shape[3];
74	        out_w = shape[4];
75	        d = out_d - pad_d_start - pad_d_end;
76	        h = out_h - pad_top - pad_bottom;
77	        w = out_w - pad_left - pad_right;
78	    }
79	
80	    TORCH_CHECK(h > 0 && w > 0, "Invalid padding: output spatial dims must be positive");
81	    if (ndim == 5) {
82	        TORCH_CHECK(d > 0, "Invalid padding: output depth must be positive");
83	    }
84	
85	    // Create output tensor
86	    std::vector<int64_t> out_shape;
87	    if (ndim == 4) {
88	        out_shape = {n, c, h, w};
89	    } else {
90	        out_shape = {n, c, d, h, w};
91	    }
92	    auto grad_input = at::empty(out_shape, grad_output.options());
93	
94	    // Get platform info
95	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
96	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
97	    uint64_t ubSize;
98	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
99	
100	    // Calculate total output elements
101	    int64_t totalLength = grad_input.numel();
102	
103	    // Block-level tiling
104	    int64_t totalLengthCoreAlign = (totalLength + coreNum - 1) / coreNum;
105	    totalLengthCoreAlign = (totalLengthCoreAlign + 127) / 128 * 128;
106	
107	    int64_t formerNum = totalLength / totalLengthCoreAlign;
108	    int64_t formerLength = totalLengthCoreAlign;
109	    int64_t tailNum = (totalLength % totalLengthCoreAlign != 0) ? 1 : 0;
110	    int64_t tailLength = totalLength - formerNum * formerLength;
111	
112	    // UB-level tiling
113	    int64_t bufferCoefficient = (dtype == at::kFloat) ? 20 : 16;
114	    int64_t tileLength = (ubSize / bufferCoefficient) / sizeof(float);
115	    tileLength = (tileLength + 7) / 8 * 8;
116	    if (tileLength > totalLengthCoreAlign) {
117	        tileLength = totalLengthCoreAlign;
118	    }
119	    if (tileLength < 8) {
120	        tileLength = 8;
121	    }
122	
123	    // Tiling data (22 uint32_t values)
124	    uint32_t tilingData[22];
125	    tilingData[0] = static_cast<uint32_t>(n);
126	    tilingData[1] = static_cast<uint32_t>(c);
127	    tilingData[2] = static_cast<uint32_t>(h);
128	    tilingData[3] = static_cast<uint32_t>(w);
129	    tilingData[4] = static_cast<uint32_t>(out_h);
130	    tilingData[5] = static_cast<uint32_t>(out_w);
131	    tilingData[6] = static_cast<uint32_t>(pad_top);
132	    tilingData[7] = static_cast<uint32_t>(pad_bottom);
133	    tilingData[8] = static_cast<uint32_t>(pad_left);
134	    tilingData[9] = static_cast<uint32_t>(pad_right);
135	    tilingData[10] = static_cast<uint32_t>(ndim);
136	    tilingData[11] = static_cast<uint32_t>(d);
137	    tilingData[12] = static_cast<uint32_t>(out_d);
138	    tilingData[13] = static_cast<uint32_t>(pad_d_start);
139	    tilingData[14] = static_cast<uint32_t>(pad_d_end);
140	    tilingData[15] = static_cast<uint32_t>(totalLength);
141	    tilingData[16] = static_cast<uint32_t>(tileLength);
142	    tilingData[17] = static_cast<uint32_t>(formerNum);
143	    tilingData[18] = static_cast<uint32_t>(formerLength);
144	    tilingData[19] = static_cast<uint32_t>(tailNum);
145	    tilingData[20] = static_cast<uint32_t>(tailLength);
146	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
147	    int64_t dtypeFlag = 0;
148	    if (dtype == at::kHalf) {
149	        dtypeFlag = 1;
150	    } else if (dtype == at::kBFloat16) {
151	        dtypeFlag = 2;
152	    }
153	    tilingData[21] = static_cast<uint32_t>(dtypeFlag);
154	
155	    // Allocate workspace for tiling data on NPU
156	    auto tiling_tensor = at::empty({22}, at::TensorOptions().dtype(at::kInt).device(grad_output.device()));
157	    tiling_tensor.copy_(at::from_blob(tilingData, {22}, at::TensorOptions().dtype(at::kInt)));
158	
159	    int64_t blockDim = coreNum;
160	
161	    // Launch kernel - aclrtlaunch only accepts 3 tensor args + tiling
162	    auto grad_output_ref = grad_output;
163	    auto grad_input_ref = grad_input;
164	    auto tiling_ref = tiling_tensor;
165	
166	    EXEC_KERNEL_CMD(padv3gradreplication, blockDim,
167	                    grad_output_ref, grad_input_ref, tiling_ref);
168	
169	    return grad_input;
170	}
171	
172	} // namespace ascend_kernel
